def rich_case(J=512,S=256,F=32,G=32,q=4,B=8,R=4,span=1,seed=5,tmax=10**9,tgmax=8):
    rng=random.Random(seed)
    times=[int(i*tmax/max(1,S-1)) for i in range(S)]
    slots=[[times[i], q, 0 if i==0 else R] for i in range(S)]
    groups=[]
    for g in range(G):
        p = -1 if rng.random()<.4 else rng.randint(0,max(0,g-1))
        groups.append([p, rng.randint(4,60)])
    flows=[]
    for f in range(F):
        tg=rng.randint(1,tgmax)
        gp = -1 if (not groups or rng.random()<.25) else rng.randint(0,G-1)
        flows.append([tg, rng.randint(tg,40), gp, rng.randint(0,6)])
    windows=[]
    for j in range(J):
        s0=rng.randint(0,S-1)
        lo=times[s0]
        hi=min(times[-1], times[min(S-1,s0+span)])
        ready = lo
        exp = hi
        if rng.random()<0.08:
            ready = 0; exp = times[-1]
        windows.append([rng.randint(0,F-1), ready, exp, rng.randint(1,65535), rng.randint(1,320),
                        rng.randint(0,65535)//rng.choice([1,1,1,2,10]), rng.randint(1,1000),
                        [[rng.randint(0,1500),rng.randint(0,2560)] for _ in range(9)]])
    return {'model':rng.choice(['cnn','rnn']),'class_values':[rng.randint(1,1000) for _ in range(7)],
            'stats':[rng.randint(1,300)]*3,'bucket':[B,I0] if False else [B,rng.randint(0,B)],
            'slots':slots,'flows':flows,'groups':groups,'windows':windows}
PYEOF
