import json, random, sys, time
sys.path.insert(0,'/workspace/dev'); sys.path.insert(0,'/workspace/vendor'); sys.path.insert(0,'/workspace/submission')
import verify, controller, perf
def go(c, label, check=True):
    req={'version':3,'cases':[c]}
    t=time.time(); resp=controller.run(json.dumps(req).encode()); dt=time.time()-t
    r=resp['results'][0]
    line='%-22s %.2fs ratio=%s U=%d A=%d nsel=%d' % (label, dt, r['ratio'], r['utility'], r['age'], sum(1 for a in r['assignment'] if a>=0))
    if check:
        try:
            verify.check_request(req,resp); line+='  OK'
        except Exception as e:
            line+='  FAIL '+type(e).__name__+' '+str(e)[:120]
    print(line, flush=True)
which=sys.argv[1] if len(sys.argv)>1 else 'rich'
if which=='rich': go(perf.rich_case(), 'rich-512x256')
elif which=='narrow': go(perf.rich_case(span=2, J=512, S=256), 'narrow-span2')
elif which=='tiny': go(perf.rich_case(span=0, J=512, S=256), 'exact-slot')
elif which=='full': go(perf.rich_case(q=512,B=512,R=0,I=512,J=512,S=256), 'all-at-once')
elif which=='groups': go(perf.rich_case(F=32,G=32,tgmax=64,q=64,B=64,R=8), 'deep-groups')
PYEOF
